import copy as _input_copy

def _isolated_call(fn, *args, **kwargs):
    copied_args, copied_kwargs = _input_copy.deepcopy((args, kwargs))
    return fn(*copied_args, **copied_kwargs)

import numpy as np
mu = np.array([-0.5, -0.37, -0.25, -0.1])
e = np.array([0.08, 0.11, 0.17])
t = _material_fixture(mu, e)
q = np.array([-0.1, -0.47, -0.5, -0.2, -0.37])
bad = t.copy()
bad[1, 1, 2] = np.nan

def _value_error_code(fn, *args):
    try:
        _isolated_call(fn, *args)
    except ValueError:
        return 1.0
    except Exception:
        return -1.0
    return 0.0
assert np.allclose(_value_error_code(material_fields, mu, bad, q), target)

